CREATE TABLE IF NOT EXISTS grading_policies ( id UUID PRIMARY KEY DEFAULT gen_random_uuid(), school_id UUID REFERENCES schools(id), teacher_id UUID REFERENCES profiles(id), class TEXT NOT NULL, subject_id UUID REFERENCES subjects(id), mid_term_weight INT DEFAULT 30, final_term_weight INT DEFAULT 40, attendance_weight INT DEFAULT 5, assignment_weight INT DEFAULT 10, class_test_weight INT DEFAULT 10, lab_weight INT DEFAULT 5, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW() ); 
